using ClampFn = int (*)(int value, int low, int high);

bool passesMyTests(ClampFn clampTo)
{
    // One check is not enough to tell a good implementation from a bad one.
    return clampTo(5, 0, 10) == 5;
}

unitTests:
namespace mutants {
    int correct(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }
    int ignoresLow(int v, int, int hi) { return v > hi ? hi : v; }
    int ignoresHigh(int v, int lo, int) { return v < lo ? lo : v; }
    int swapsBounds(int v, int lo, int hi) { return v < lo ? hi : (v > hi ? lo : v); }
    int offByOneAbove(int v, int lo, int hi) { return v < lo ? lo : (v >= hi ? hi - 1 : v); }
    int offByOneBelow(int v, int lo, int hi) { return v <= lo ? lo + 1 : (v > hi ? hi : v); }
    int assumesZeroLow(int v, int, int hi) { return v < 0 ? 0 : (v > hi ? hi : v); }
    int alwaysLow(int, int lo, int) { return lo; }
    int usesAbsolute(int v, int lo, int hi) { const int a{ v < 0 ? -v : v }; return a < lo ? lo : (a > hi ? hi : a); }
}

TEST("a correct implementation passes your tests") { CHECK(passesMyTests(mutants::correct)); }
TEST("caught: ignores the lower bound") { CHECK(!passesMyTests(mutants::ignoresLow)); }
TEST("caught: ignores the upper bound") { CHECK(!passesMyTests(mutants::ignoresHigh)); }
TEST("caught: returns the wrong bound") { CHECK(!passesMyTests(mutants::swapsBounds)); }
TEST("caught: wrong exactly at the upper edge") { CHECK(!passesMyTests(mutants::offByOneAbove)); }
TEST("caught: wrong exactly at the lower edge") { CHECK(!passesMyTests(mutants::offByOneBelow)); }
TEST("caught: assumes the range starts at zero") { CHECK(!passesMyTests(mutants::assumesZeroLow)); }
TEST("caught: always returns the lower bound") { CHECK(!passesMyTests(mutants::alwaysLow)); }
TEST("caught: mishandles negative values") { CHECK(!passesMyTests(mutants::usesAbsolute)); }

